var h={wavelength:550,slitSeparation:.35,screenDistance:1.2,slitWidth:.08,visibility:1,timeStep:.008333333333333333},b=i=>Math.abs(i)<1e-10?1:Math.sin(i)/i;function o(i,t){let e=t.wavelength*1e-9,n=t.slitWidth*.001,a=t.slitSeparation*.001,r=i*.001,s=r/Math.hypot(t.screenDistance,r),c=Math.PI*n*s/e,S=Math.PI*a*s/e,u=b(c)**2;return Math.max(0,Math.min(1,u*(1+t.visibility*Math.cos(2*S))/(1+t.visibility)))}function m(i){return i.wavelength*.001*i.screenDistance/i.slitSeparation}var l=class{createInitialState(t){return{t:0,detectorY:-9,phase:0,profile:Array.from({length:181},(n,a)=>{let r=-9+18*a/180;return o(r,t)})}}step(t,e){t.t=Math.min(8,t.t+e),t.detectorY=-9+18*t.t/8,t.phase=t.t*.7%1}time(t){return t.t}isFinished(t){return t.t>=8-1e-9}measure(t,e){let n=m(e);return{time:t.t,wavelength:e.wavelength,slitSeparation:e.slitSeparation,screenDistance:e.screenDistance,slitWidth:e.slitWidth,fringeSpacing:n,firstDark:n/2,detectorY:t.detectorY,intensity:100*o(t.detectorY,e),visibility:100*e.visibility}}};export{h as a,o as b,m as c,l as d};
